# ACM 模式：用 input() 或 sys.stdin 读输入，用 print 输出答案
# 输入格式：第一行 k；随后 k 行，每行为 "n v1 v2 ... vn"（n = 0 时只有 0）
import sys

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

lines = sys.stdin.read().split('\n')
k = int(lines[0])
nodes = []
for i in range(k):
    vals = list(map(int,lines[i+1].split())) 
    if vals[0] == 0:
        continue
    head = ListNode()
    h = head
    for j in vals[1:]:
        h.next = ListNode(j)
        h=h.next
    nodes.append(head)
def merge(h1,h2):
    head = ListNode()
    h = head
    while h1 and h2:
        if h1.val < h2.val:
            h.next = h1
            h1=h1.next
            h = h.next
        else:
            h.next = h2
            h2 = h2.next
            h = h.next
    if h1:
        h.next = h1
    else:
        h.next = h2
    return head.next
def get_ans(l,r):
    if l == r:
        return nodes[l].next
    if r < l :
        return
    mid = (l+r)//2
    return merge(get_ans(l,mid),get_ans(mid+1,r))

head = get_ans(0,len(nodes)-1)
ans = []
while head:
    ans.append(head.val)
    head = head.next
if not ans:
    print()
else:
    print(' '.join(map(str,ans)))
# 解析出 k 个链表的值数组，构造链表，合并后用 print 输出结果

